// El 200 no garantiza que la respuesta sirva.
// Este nodo clasifica cada fila: utilizable o no, y por qué.

// Casas que legítimamente no publican precio de compra.
const SIN_COMPRA = ['tarjeta'];

function aNumero(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);                 // "1015.00" -> 1015
  return Number.isFinite(n) ? n : NaN; // NaN marca "vino algo que no es un número"
}

const salida = [];

for (const item of $input.all()) {
  const fila = item.json;

  const compra = aNumero(fila.compra);
  const venta = aNumero(fila.venta);

  let motivo = null;

  if (!fila.casa) {
    motivo = 'casa_ausente';
  } else if (Number.isNaN(compra) || Number.isNaN(venta)) {
    motivo = 'importe_no_numerico';
  } else if (venta === null) {
    motivo = 'venta_ausente';
  } else if (compra === null && !SIN_COMPRA.includes(fila.casa)) {
    motivo = 'compra_ausente';
  } else if (compra !== null && venta < compra) {
    // Numéricamente posible, comercialmente imposible.
    motivo = 'venta_menor_que_compra';
  } else if (!fila.fechaActualizacion) {
    motivo = 'fecha_ausente';
  }

  salida.push({
    json: {
      casa: fila.casa ?? null,
      nombre: fila.nombre ?? null,
      compra,
      venta,
      fechaActualizacion: fila.fechaActualizacion ?? null,
      _valido: motivo === null,
      _motivo: motivo,
      _original: fila,
    },
  });
}

return salida;

// Un solo envío con todas las cotizaciones, no uno por fila.
// Sin este nodo, el HTTP de abajo se ejecuta una vez por item y publica
// seis gists de una sola fila cada uno.

const mercados = $input.all().map((i) => i.json);

return [
  {
    json: {
      panel: 'cotizaciones-usd',
      generado: new Date().toISOString(),
      mercados: mercados.length,
      cotizaciones: mercados,
    },
  },
];

// Una sola rama de aviso para todos los nodos que pueden fallar.
// El item que llega por una salida de error trae el error en $json.error.

const err = $json.error || {};
const codigo = err.httpCode ? Number(err.httpCode) : null;
const mensaje = err.message ?? String(err);

// GitHub devuelve 403 para dos cosas distintas: "no tenés permiso" y "te
// pasaste del límite". La primera es permanente y la segunda no. El código
// solo no alcanza: hay que mirar el cuerpo.
const porLimite = /rate limit|too many requests|abuse detection/i.test(mensaje);

// Distinguir transitorio de permanente cambia qué se hace después:
// el transitorio ya reintentó solo, el permanente necesita a una persona.
const transitorio =
  codigo === 429 ||
  (codigo !== null && codigo >= 500) ||
  codigo === null ||
  (codigo === 403 && porLimite);

// El 401 y el 403 merecen su propio texto: casi siempre es la credencial,
// y quien lee el aviso a las tres de la mañana necesita saberlo.
let queHacer;
if (codigo === 401) {
  queHacer = 'La credencial no sirve: token ausente, mal escrito o vencido.';
} else if (codigo === 403 && porLimite) {
  queHacer = 'Límite de uso agotado. Esperar a que se reponga, o repartir la carga.';
} else if (codigo === 403) {
  queHacer = 'Autenticado, pero al token le falta el permiso que pide este endpoint.';
} else if (transitorio) {
  queHacer = 'Ya se reintentó y siguió fallando. Revisar el estado del proveedor.';
} else {
  queHacer = 'No tiene sentido reintentar. Revisar URL, cuerpo enviado o permisos.';
}

return [
  {
    json: {
      flujo: $workflow.name,
      ejecucion: $execution.id,
      nodo: err.node?.name ?? 'desconocido',
      codigo_http: codigo,
      mensaje: err.message ?? String(err),
      clase: transitorio ? 'transitorio' : 'permanente',
      que_hacer: queHacer,
      cuando: new Date().toISOString(),
    },
  },
];
